import os,subprocess
from pathlib import Path
src=Path('/srv/pink-iptv-device-proof')
repo=Path('/srv/pink-iptv')
parent=repo/'tests'
dst=parent/'device-proof'
ignore=repo/'.git/info/exclude'
marker='/tests/device-proof/'
def unit(name):
 r=subprocess.run(['systemctl','is-active',name+'.service'],capture_output=True,text=True,timeout=8)
 return r.stdout.strip()
names=['pink-iptv-backend','pink-vpn','fadego-staging','lowcost-europa','pm2-root','nginx','postgresql@16-main']
before={x:unit(x) for x in names}
for x in names:
 if before[x]!='active':raise RuntimeError('Protected service not active before: '+x)
if not src.is_dir() or src.is_symlink() or not repo.is_dir() or repo.is_symlink() or not (repo/'.git').is_dir():
 raise RuntimeError('Source or Git checkout not verified')
if dst.exists() or dst.is_symlink() or parent.exists() or parent.is_symlink():
 raise RuntimeError('Target path not empty / already exists')
if src.stat().st_dev!=repo.stat().st_dev:raise RuntimeError('Cannot do atomic same-filesystem relocation')
if ignore.is_symlink() or not ignore.is_file():raise RuntimeError('Git exclude is not a regular file')
original_exclude=ignore.read_bytes()
if marker.encode() in original_exclude:raise RuntimeError('Ignore entry already exists; review')
if src.stat().st_nlink<2:raise RuntimeError('Invalid source directory')
inode=src.stat().st_ino
size=int(subprocess.run(['du','-x','-s','-B1',str(src)],capture_output=True,text=True,check=True,timeout=50).stdout.split()[0])
print('PINK_SOURCE_BYTES='+str(size))
print('PINK_SOURCE_INODE='+str(inode))
for proc in Path('/proc').iterdir():
 if not proc.name.isdigit():continue
 try:
  cwd=os.readlink(proc/'cwd')
  if cwd==str(src) or cwd.startswith(str(src)+'/'):raise RuntimeError('Process CWD uses source: '+proc.name)
 except OSError:pass
 try:
  for fd in (proc/'fd').iterdir():
   try:
    target=os.readlink(fd)
    if target==str(src) or target.startswith(str(src)+'/'):
     raise RuntimeError('Process FD uses source: '+proc.name)
   except OSError:pass
 except OSError:pass
status_before=subprocess.run(['git','-C',str(repo),'status','--porcelain','--untracked-files=no'],capture_output=True,text=True,timeout=15)
if status_before.returncode!=0:raise RuntimeError('Git status unavailable')
pre_changed=status_before.stdout.splitlines()
try:
 ignore.write_bytes(original_exclude+(b'\n' if original_exclude and not original_exclude.endswith(b'\n') else b'')+b'\n# Local Android proof artifacts (not for Git)\n'+marker.encode()+b'\n')
 parent.mkdir(mode=0o750)
 os.chown(parent,repo.stat().st_uid,repo.stat().st_gid)
 src.rename(dst)
 if src.exists() or dst.stat().st_ino!=inode:raise RuntimeError('Post-move inode/source check failed')
 r=subprocess.run(['git','-C',str(repo),'check-ignore','-q','--no-index',str(dst/'apk')],capture_output=True,text=True,timeout=15)
 if r.returncode!=0:raise RuntimeError('Git ignore did not match proofs')
 status_after=subprocess.run(['git','-C',str(repo),'status','--porcelain','--untracked-files=no'],capture_output=True,text=True,timeout=15)
 if status_after.returncode!=0 or status_after.stdout.splitlines()!=pre_changed:
  raise RuntimeError('Existing tracked changes affected by migration')
 after={x:unit(x) for x in names}
 if after!=before:raise RuntimeError('Protected service status changed')
 size_after=int(subprocess.run(['du','-x','-s','-B1',str(dst)],capture_output=True,text=True,check=True,timeout=50).stdout.split()[0])
 if size_after!=size:raise RuntimeError('Post-move size mismatch')
except Exception:
 if dst.is_dir() and not src.exists():dst.rename(src)
 ignore.write_bytes(original_exclude)
 if parent.exists() and not any(parent.iterdir()):parent.rmdir()
 print('PINK_ROLLBACK=APPLIED')
 raise
print('PINK_SOURCE_ABSENT='+str(not src.exists()))
print('PINK_TARGET='+str(dst))
print('PINK_TARGET_BYTES='+str(size_after))
print('GIT_IGNORES_PROOF=yes')
print('TRACKED_GIT_CHANGES_UNTOUCHED='+str(len(pre_changed)))
print('ACTIVE_SERVICES_VERIFIED='+','.join(names))
print('SPACE_FREED_BY_MOVE_BYTES=0')
print('PINK_RELOCATION=PASS')
PY
